def fibonacci(n):
    if n <= 0:
        return "Input must be a positive integer."
    elif n == 1 or n == 2:
        return 1
    else:
        a = 1  # F1
        b = 1  # F2
        for _ in range(3, n + 1):
            next_fib = a + b
            a = b
            b = next_fib
        return b

print(f"The 30th Fibonacci number (F1=F2=1) is: {fibonacci(30)}")
